###############################################################################
# BEGIN fix (52 / 387) for 'xccdf_org.ssgproject.content_rule_enable_gpgcheck_for_all_repositories'
###############################################################################
(>&2 echo "Remediating rule 52/387: 'xccdf_org.ssgproject.content_rule_enable_gpgcheck_for_all_repositories'")

function replace_all_gpgcheck {
    sed -i 's/gpgcheck\s*=.*/gpgcheck=1/g' /etc/yum.repos.d/*
}

function add_gpgcheck_where_missing {
    for repofile in /etc/yum.repos.d/* ; do
        declare -a sections_without_gpgcheck
        section="false"
        section_has_gpgcheck="false"
        section_name=""
        while IFS= read -r line; do
            if grep -qP '^\[.*\]$' <( echo "$line" ) ; then
                # new section starts
                if [[ "$section" == "true" ]] && [[ "$section_has_gpgcheck" == "false" ]] ; then
                    sections_without_gpgcheck+=("$section_name")
                    section="false"
                fi
                section="true"
                section_has_gpgcheck="false"
                section_name=$(echo "$line" | sed -n 's/^\[\(.*\)\]$/\1/p')
            fi
            if grep -qP '^\s*gpgcheck\s*=\s*' <( echo "$line" ) ; then
                section_has_gpgcheck="true"
            fi
        done < "$repofile"
        if [[ "$section" == "true" ]] && [[ "$section_has_gpgcheck" == "false" ]] ; then
            sections_without_gpgcheck+=("$section_name")
            section="false"
        fi

        for x in "${sections_without_gpgcheck[@]}" ; do
            sed -i "s/^\[$x\]/&\ngpgcheck=1/" "$repofile"
        done
    done
}

replace_all_gpgcheck
add_gpgcheck_where_missing

# END fix for 'xccdf_org.ssgproject.content_rule_enable_gpgcheck_for_all_repositories'

###############################################################################
# BEGIN fix (53 / 387) for 'xccdf_org.ssgproject.content_rule_ensure_epel_repos_disabled'
###############################################################################
(>&2 echo "Remediating rule 53/387: 'xccdf_org.ssgproject.content_rule_ensure_epel_repos_disabled'")

# Ensure dnf-plugins-core is available for dnf config-manager
if ! command -v dnf &> /dev/null; then
    # System uses yum instead of dnf
    if command -v yum-config-manager &> /dev/null; then
        CONFIG_MANAGER="yum-config-manager"
    else
        echo "Neither dnf nor yum-config-manager found, cannot disable repositories" >&2
        exit 1
    fi
else
    # System uses dnf
    if ! command -v dnf config-manager &> /dev/null 2>&1; then
        dnf install -y dnf-plugins-core
    fi
    CONFIG_MANAGER="dnf config-manager"
fi

# Find all EPEL repository IDs by name pattern
for repo_file in /etc/yum.repos.d/*.repo; do
    [ -f "$repo_file" ] || continue

    # Extract repository IDs that contain "epel" (case-insensitive)
    while IFS= read -r repo_id; do
        $CONFIG_MANAGER --set-disabled "$repo_id"
    done < <(grep -ioP '^\[\K[^\]]*epel[^\]]*(?=\])' "$repo_file")
done

# END fix for 'xccdf_org.ssgproject.content_rule_ensure_epel_repos_disabled'

###############################################################################
# BEGIN fix (54 / 387) for 'xccdf_org.ssgproject.content_rule_ensure_gpgcheck_local_packages'
###############################################################################
(>&2 echo "Remediating rule 54/387: 'xccdf_org.ssgproject.content_rule_ensure_gpgcheck_local_packages'")
# Remediation is applicable only in certain platforms
if rpm --quiet -q yum; then

# Strip any search characters in the key arg so that the key can be replaced without
# adding any search characters to the config file.
stripped_key=$(sed 's/[\^=\$,;+]*//g' <<< "^localpkg_gpgcheck")

# shellcheck disable=SC2059
printf -v formatted_output "%s = %s" "$stripped_key" "1"

# If the key exists, change it. Otherwise, add it to the config_file.
# We search for the key string followed by a word boundary (matched by \>),
# so if we search for 'setting', 'setting2' won't match.
if LC_ALL=C grep -q -m 1 -i -e "^localpkg_gpgcheck\\>" "/etc/yum.conf"; then
    escaped_formatted_output=$(sed -e 's|/|\\/|g' <<< "$formatted_output")
    LC_ALL=C sed -i --follow-symlinks "s/^localpkg_gpgcheck\\>.*/$escaped_formatted_output/gi" "/etc/yum.conf"
else
    if [[ -s "/etc/yum.conf" ]] && [[ -n "$(tail -c 1 -- "/etc/yum.conf" || true)" ]]; then
        LC_ALL=C sed -i --follow-symlinks '$a'\\ "/etc/yum.conf"
    fi
    cce="CCE-80791-7"
    printf '# Per %s: Set %s in %s\n' "${cce}" "${formatted_output}" "/etc/yum.conf" >> "/etc/yum.conf"
    printf '%s\n' "$formatted_output" >> "/etc/yum.conf"
fi

else
    >&2 echo 'Remediation is not applicable, nothing was done'
fi

# END fix for 'xccdf_org.ssgproject.content_rule_ensure_gpgcheck_local_packages'

###############################################################################
# BEGIN fix (55 / 387) for 'xccdf_org.ssgproject.content_rule_ensure_redhat_gpgkey_installed'
###############################################################################
(>&2 echo "Remediating rule 55/387: 'xccdf_org.ssgproject.content_rule_ensure_redhat_gpgkey_installed'")
# The two fingerprints below are retrieved from https://access.redhat.com/security/team/key
readonly REDHAT_RELEASE_FINGERPRINT="567E347AD0044ADE55BA8A5F199E2F91FD431D51"
readonly REDHAT_AUXILIARY_FINGERPRINT="6A6AA7C97C8890AEC6AEBFE2F76F66C3D4082792"


# Location of the key we would like to import (once it's integrity verified)
readonly REDHAT_RELEASE_KEY="/etc/pki/rpm-gpg/RPM-GPG-KEY-redhat-release"

RPM_GPG_DIR_PERMS=$(stat -c %a "$(dirname "$REDHAT_RELEASE_KEY")")

# Verify /etc/pki/rpm-gpg directory permissions are safe
if [ "${RPM_GPG_DIR_PERMS}" -le "755" ]
then
  # If they are safe, try to obtain fingerprints from the key file
  # (to ensure there won't be e.g. CRC error).

  readarray -t GPG_OUT < <(gpg --show-keys --with-fingerprint --with-colons "$REDHAT_RELEASE_KEY" | grep -A1 "^pub" | grep "^fpr" | cut -d ":" -f 10)

  GPG_RESULT=$?
  # No CRC error, safe to proceed
  if [ "${GPG_RESULT}" -eq "0" ]
  then
  # If $REDHAT_RELEASE_KEY file doesn't contain any keys with unknown fingerprint, import it

    echo "${GPG_OUT[*]}" | grep -vE "${REDHAT_RELEASE_FINGERPRINT}|${REDHAT_AUXILIARY_FINGERPRINT}" || rpm --import "${REDHAT_RELEASE_KEY}"

  fi
fi

# END fix for 'xccdf_org.ssgproject.content_rule_ensure_redhat_gpgkey_installed'

